// The modules that the bundler of the host provides: the class names of a CSS module, and the URL of the sprite of the
// SVG symbols (`@akohn/dashql-svg-symbols`, generated by //packages/dashql-app:svg_symbols, see symbol_icon.tsx)
declare module '*.module.css';
declare module '@akohn/dashql-svg-symbols' {
    const url: string;
    export default url;
}
